import{_ as a,o as s,c as o,ag as t}from"./chunks/framework.DCk0k6gb.js";const h=JSON.parse('{"title":"sa-token-rust","description":"","frontmatter":{},"headers":[],"relativePath":"zh/index.md","filePath":"zh/index.md"}'),n={name:"zh/index.md"};function r(c,e,i,p,d,l){return s(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="sa-token-rust" tabindex="-1">sa-token-rust <a class="header-anchor" href="#sa-token-rust" aria-label="Permalink to &quot;sa-token-rust&quot;">​</a></h1><p><a href="/sa-token-rust/">English</a></p><p>轻量级 Rust 认证授权框架。设计灵感来自 <a href="https://github.com/dromara/sa-token" target="_blank" rel="noreferrer">Dromara sa-token</a>；本仓库为独立实现（MIT OR Apache-2.0），见仓库根目录 <code>NOTICE</code>。</p><p>面向 Web 与 gRPC：在 Axum、Actix-web、Poem、Rocket、Warp、Salvo、Tide、Gotham、Ntex 与 Tonic 上，使用同一套 <code>StpUtil</code> / <code>SaTokenState</code> 心智模型完成登录、鉴权与会话管理。</p><p><strong>从这里开始：</strong> <a href="/sa-token-rust/zh/guide/quick-start.html">快速入门</a>。从 0.1.x 升级请先读 <a href="/sa-token-rust/zh/guide/migration-0.2.html">迁移到 0.2</a>。</p><h2 id="它能做什么" tabindex="-1">它能做什么 <a class="header-anchor" href="#它能做什么" aria-label="Permalink to &quot;它能做什么&quot;">​</a></h2><p>登录、登出、踢人、顶号由核心 <code>AuthService</code> 编排。应用侧通常调用 <code>StpUtil::login</code>、<code>logout</code>、<code>kick_out</code> 等静态门面。例如：<code>let token = StpUtil::login(&quot;10001&quot;).await?;</code></p><p>权限与角色经 <code>AuthzService</code>。你可以在代码里用 <code>has_permission</code> / <code>check_role</code>，也可以在 handler 上挂宏，例如 <code>#[sa_check_permission(&quot;user:add&quot;)]</code>。通配匹配与 Exact 策略见 <a href="/sa-token-rust/zh/guide/permission-matching.html">权限匹配与宏</a>。</p><p>中间件路径鉴权使用 <code>PathAuthConfig</code>。公开路由必须写入 <code>exclude</code>。<code>#[sa_ignore]</code> 只跳过宏插入的检查，<strong>不会</strong>跳过 Layer / 中间件。详见 <a href="/sa-token-rust/zh/guide/path-auth.html">路径鉴权</a>。</p><p>存储后端 Memory、Redis、Database 统一经 <code>SaTokenDao</code>。插件通过 Cargo feature 切换后端，键布局由 <code>SaKeys</code> 管理。Token 读写走核心 <code>token_io</code>（<code>read_token</code> / <code>write_token_cookie</code>），与各框架适配器一致。</p><p>JWT、Nonce、Refresh、OAuth2（含 PKCE）、SSO、WebSocket 鉴权、在线 presence、分布式 Session 与事件总线各自有独立指南，可按需接入。</p><p>多账号用 <code>login_type</code> 隔离体系，例如管理端与用户端。可使用 <code>StpUtil::builder(...).login_type(&quot;admin&quot;)</code>，或 <code>SaLogic::new(&quot;admin&quot;, manager)</code> 绑定某一账号门面。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sa-token-rust/</span></span>
<span class="line"><span>├── sa-token-core/           # Dao、keys、service、token_io、oauth2/、sso/、StpUtil、SaLogic</span></span>
<span class="line"><span>├── sa-token-adapter/        # SaStorage、SaSerializer、SaRequest / SaResponse、scan</span></span>
<span class="line"><span>├── sa-token-macro/          # 过程宏</span></span>
<span class="line"><span>├── sa-token-plugin-common/  # SaTokenState、rejection（各插件再导出）</span></span>
<span class="line"><span>├── sa-token-storage-*/      # memory / redis / database</span></span>
<span class="line"><span>├── sa-token-plugin-*/       # axum、actix-web、poem、rocket、warp、salvo、tide、gotham、ntex、tonic</span></span>
<span class="line"><span>└── doc/                     # 本站点（VitePress）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>门面 crate（Actix-web、Rocket、Salvo、Gotham、Ntex）通过 Cargo features 选择框架大版本。共享类型在 <code>sa-token-plugin-common</code>，不再有 <code>*-core</code> crate。</p><h2 id="社区" tabindex="-1">社区 <a class="header-anchor" href="#社区" aria-label="Permalink to &quot;社区&quot;">​</a></h2><p>微信交流群：</p><p><img src="https://sa-token.cc/big-file/contact/sa-token-rust--wx-group-qr.png?v=5" alt="sa-token-rust 微信群"></p><p>Issues：<a href="https://github.com/sa-tokens/sa-token-rust/issues" target="_blank" rel="noreferrer">https://github.com/sa-tokens/sa-token-rust/issues</a></p><h2 id="许可证" tabindex="-1">许可证 <a class="header-anchor" href="#许可证" aria-label="Permalink to &quot;许可证&quot;">​</a></h2><p>MIT OR Apache-2.0。见 <code>LICENSE-MIT</code> 与 <code>LICENSE-APACHE</code>。</p>`,21)])])}const m=a(n,[["render",r]]);export{h as __pageData,m as default};
